import{_ as s,o as e,c as n,S as t}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"Github如何省略每次输入验证信息","description":"","frontmatter":{"title":"Github如何省略每次输入验证信息","date":"2019-06-23 20:21","comments":true,"archives":2019,"tags":["github"]},"headers":[],"relativePath":"posts/2019-06-23-github-omit-auth/index.md","filePath":"posts/2019/2019-06-23-github-omit-auth.md"}'),o={name:"posts/2019-06-23-github-omit-auth/index.md"};function p(l,a,r,i,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t('<p>项目开发中经常会遇到 CI 自动拉取 Github 库的情况，我们个人使用的时候会手动输入账户密码信息，但是针对 CI 来说，我们一般会把敏感的认证信息放在环境变量里。所以针对认证信息的自动输入，需要做一些处理。</p><h2 id="环境变量自动替换" tabindex="-1">环境变量自动替换 <a class="header-anchor" href="#环境变量自动替换" aria-label="Permalink to &quot;环境变量自动替换&quot;">​</a></h2><p>针对 Travis CI，我们一般把认证信息放在环境变量里，所以在执行 clone 其他 repo 的时候，可以先设置认证信息。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> config</span><span style="color:#005CC5;"> --global</span><span style="color:#032F62;"> url.&quot;https://${</span><span style="color:#24292E;">CI_USER_NAME</span><span style="color:#032F62;">}:${</span><span style="color:#24292E;">CI_USER_TOKEN</span><span style="color:#032F62;">}@github.com/&quot;.insteadOf</span><span style="color:#032F62;"> &quot;https://github.com/&quot;&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这样设置的话，会自动替换 git clone 的网址。</p><h2 id="url-里面写入认证信息" tabindex="-1">URL 里面写入认证信息 <a class="header-anchor" href="#url-里面写入认证信息" aria-label="Permalink to &quot;URL 里面写入认证信息&quot;">​</a></h2><p>有时候需要以另外一个身份进行 clone repo 的时候，会直接在 repo 的 URL 前面加上认证信息。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> clone</span><span style="color:#032F62;"> https://</span><span style="color:#24292E;">${USER_NAME}</span><span style="color:#032F62;">:</span><span style="color:#24292E;">${USER_TOKEN}</span><span style="color:#032F62;">@github.com/{username}/{repo}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这样可以很方便的 clone 信息，但是认证信息会存在当前库的 git config 文件里，有泄漏的风险。</p><h2 id="netrc-设置" tabindex="-1">netrc 设置 <a class="header-anchor" href="#netrc-设置" aria-label="Permalink to &quot;netrc 设置&quot;">​</a></h2><p>netr 文件用于存储网站的认证信息，一般位置在<code>~/.netrc</code>。格式是：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>machine github.com</span></span>\n<span class="line"><span>login username</span></span>\n<span class="line"><span>password xxxxxxx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>总共有这么三种省略认证信息的方式，根据实际情况选择自己方便的一种认证方式即可。</p><p>参考：</p><p><a href="https://qiita.com/azusanakano/items/8dc1d7e384b00239d4d9" target="_blank" rel="noreferrer">GitHub でユーザ名・パスワード省略</a></p>',16)])])}const b=s(o,[["render",p]]);export{h as __pageData,b as default};
